/**
 * Rotating card tints — gives list/grid cards a subtle, distinct background so
 * items are visually separated on mobile (where borders alone read flat).
 *
 * Usage: `className={cardTint(index)}` on the card container. Colors are gentle
 * pastels that work in light mode and stay readable; dark-mode variants keep
 * them muted.
 */
// Solid -50/-100 shades (no opacity modifier) so they're always generated by
// Tailwind and clearly visible on mobile screens.
const TINTS = [
  'bg-blue-50 border-blue-200 dark:bg-blue-950/30 dark:border-blue-900/40',
  'bg-emerald-50 border-emerald-200 dark:bg-emerald-950/30 dark:border-emerald-900/40',
  'bg-amber-50 border-amber-200 dark:bg-amber-950/30 dark:border-amber-900/40',
  'bg-violet-50 border-violet-200 dark:bg-violet-950/30 dark:border-violet-900/40',
  'bg-rose-50 border-rose-200 dark:bg-rose-950/30 dark:border-rose-900/40',
  'bg-sky-50 border-sky-200 dark:bg-sky-950/30 dark:border-sky-900/40',
  'bg-teal-50 border-teal-200 dark:bg-teal-950/30 dark:border-teal-900/40',
  'bg-indigo-50 border-indigo-200 dark:bg-indigo-950/30 dark:border-indigo-900/40',
];

/** Return a tint class for the given item index (rotates through the palette). */
export function cardTint(index: number): string {
  return TINTS[((index % TINTS.length) + TINTS.length) % TINTS.length];
}

export default cardTint;
